def target_tile_collection():
    if tiles.tile_at_location_equals(target_tile, sprites.dungeon.chest_closed):
        game.show_long_text("Dit is de snijplotter, hier kun je stickers mee snijden. Goed om te weten: een snijplotter is geen printer!",
            DialogLayout.BOTTOM)
        # Maak de kist open (visuele feedback)
        tiles.set_tile_at(target_tile, sprites.dungeon.chest_closed)
        info.change_score_by(1)
    elif tiles.tile_at_location_equals(target_tile, sprites.swamp.swamp_tile0):
        game.show_long_text("Verkeerde deur! Graag via de andere deur het lokaal in gaan.",
            DialogLayout.BOTTOM)
        # Maak de kist open (visuele feedback)
        tiles.set_tile_at(target_tile, sprites.swamp.swamp_tile0)
    elif tiles.tile_at_location_equals(target_tile, sprites.builtin.forest_tiles4):
        game.show_long_text("Tijdens de les niet naar de wc.", DialogLayout.BOTTOM)
        # Maak de kist open (visuele feedback)
        tiles.set_tile_at(target_tile, sprites.builtin.forest_tiles4)
    elif tiles.tile_at_location_equals(target_tile, sprites.builtin.forest_tiles8):
        game.show_long_text("Uh, dat is een meterkast, je mag ook het lokaal in gaan hoor.",
            DialogLayout.BOTTOM)
        # Maak de kist open (visuele feedback)
        tiles.set_tile_at(target_tile, sprites.builtin.forest_tiles8)
    elif tiles.tile_at_location_equals(target_tile, sprites.builtin.forest_tiles17):
        game.show_long_text("Dat is het 'oude' technieklokaal. Daar hebben we ook wel eens les met de onderbouw. Het is een magische plek waar linialen verdwijnen.",
            DialogLayout.BOTTOM)
        # Maak de kist open (visuele feedback)
        tiles.set_tile_at(target_tile, sprites.builtin.forest_tiles17)
    elif tiles.tile_at_location_equals(target_tile, sprites.swamp.swamp_tile4):
        game.show_long_text("Hier mag je je jas en tas neerleggen, goedzo!",
            DialogLayout.BOTTOM)
        # Maak de kist open (visuele feedback)
        tiles.set_tile_at(target_tile, sprites.swamp.swamp_tile4)
        info.change_score_by(1)
    else:
        pass
# 2. De Interactie (A-knop)

def on_a_pressed():
    global doel_rij, doel_kolom, target_tile
    # Speel een geluidje
    music.play(music.create_sound_effect(WaveShape.TRIANGLE,
            2699,
            3226,
            255,
            0,
            100,
            SoundExpressionEffect.NONE,
            InterpolationCurve.LINEAR),
        music.PlaybackMode.UNTIL_DONE)
    # Bereken waar de SPELER nu staat
    doel_rij = Math.floor(Character.y / 16)
    doel_kolom = Math.floor(Character.x / 16)
    # Bereken naar welke tegel we KIJKEN
    if facing_direction == "up":
        doel_rij += -1
    elif facing_direction == "down":
        doel_rij += 1
    elif facing_direction == "left":
        doel_kolom += -1
    elif facing_direction == "right":
        # CORRECTIE: Links is -1 (X wordt kleiner)
        doel_kolom += 1
    # CORRECTIE: Rechts is +1 (X wordt groter)
    # Check de tegel
    # Zorg dat 'sprites.dungeon.chest_closed' overeenkomt met de tegel in jouw editor!
    target_tile = tiles.get_tile_location(doel_kolom, doel_rij)
    target_tile_collection()
controller.A.on_event(ControllerButtonEvent.PRESSED, on_a_pressed)

