def on_forever():
    if not (is_moving):
        if controller.up.is_pressed():
            move_character(0, -50, "up")
        elif controller.down.is_pressed():
            move_character(0, 50, "down")
        elif controller.left.is_pressed():
            move_character(-50, 0, "left")
        elif controller.right.is_pressed():
            move_character(50, 0, "right")
forever(on_forever)
